//! 🧺️ Retires the actual decoder recipient and its retained original child.
use super::NativeDecodeRetirementRecipient;
use crate::{ErasedSnapshotRetirement,ValueError,retained_clone::{RetainedCloneGrant,RetainedCloneStep},retirement::{RetireOwned,RetirementCursor,RetirementStep}};
use std::mem::size_of;

#[derive(Clone,Copy,PartialEq,Eq)]
struct RecipientCloseBinding{ledger:crate::NativeAllocationIdentity,recipient:Option<u64>,work:semio_framework_value_control_contract::OriginalWorkBindingIdentity}

/// 🧳️ Keeps the same recipient and its child reply across a recorded close.
pub struct NativeDecodeRecipientCursor{owner:std::mem::ManuallyDrop<Option<NativeDecodeRetirementRecipient>>,reply:std::mem::ManuallyDrop<Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>>,invocation:Option<semio_framework_value_control_contract::OriginalEffectInvocationIdentity>,grant:Option<RetainedCloneGrant>,selected:Option<(usize,crate::RetirementDemand,u64)>,original:Option<Option<RecipientCloseBinding>>}
impl RetireOwned for NativeDecodeRetirementRecipient {
 fn retirement_ready(&self)->bool{self.close.is_empty()&&self.funding.failure_allocation.is_none()&&self.funding.failure_port.is_none()&&self.funding.failure_ledger.is_none()&&self.funding.failure_verdict.is_none()&&self.funding.failure_protocol_refusal.is_none()&&self.funding.failure_birth.terminal_is_empty()}
 type RetirementCursor=NativeDecodeRecipientCursor;fn retirement_seed(self)->Self::RetirementCursor{NativeDecodeRecipientCursor{owner:std::mem::ManuallyDrop::new(Some(self)),reply:std::mem::ManuallyDrop::new(None),invocation:None,grant:None,selected:None,original:None}}
 fn retirement_birth_bytes(&self)->Option<usize>{self.retirement_ready().then_some(size_of::<Self::RetirementCursor>())}
 fn controlled_retirement_supported()->bool{true}
}

impl NativeDecodeRecipientCursor{
 fn close_reply<'reply>(&mut self,mut original:Option<&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::OriginalEffectReply<'reply,RetirementStep,crate::OriginalRetirementFailure>,recover:bool)->Result<crate::OriginalEffectReplyComplete<'reply,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{let boundary=effect.performed_boundary();let grant=effect.grant();let mode=match original.as_deref_mut(){None=>None,Some(original)=>{let work=original.original_work().binding_identity()?;if !work.matches_effect(effect){return Err(ValueError::invariant("recipient close changed its original Work"))}Some(RecipientCloseBinding{ledger:original.ledger_identity(),recipient:original.retirement_recipient_identity(),work})}};if self.invocation.is_none(){if recover{return Err(ValueError::invariant("recipient close has no original recovery"))}let Some(owner)=self.owner.as_ref()else{return Ok(reply.complete(Ok(RetirementStep::Complete(0))))};let demand=self.next_demand(body)?;let work=self.next_computational_work(body)?;if effect.remaining_work_units()?<work||!crate::retained_clone::retained_clone_grant_admits(grant,demand){return Ok(reply.complete(Ok(RetirementStep::BudgetExhausted)))}if owner.terminal_is_empty(){if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"recipient header close exceeded original Work").into())))}self.owner.take();return Ok(reply.complete(Ok(RetirementStep::Progress(crate::RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()},effect.performed_since(boundary)?))))}let identity=effect.invocation().ok_or_else(||ValueError::invariant("recipient child lacks original invocation"))?.identity();self.invocation=Some(identity);self.grant=Some(grant);self.selected=Some((body,demand,work));self.original=Some(mode)}let identity=effect.invocation().ok_or_else(||ValueError::invariant("recipient child lost original invocation"))?.identity();if self.invocation!=Some(identity)||self.grant!=Some(grant)||self.original!=Some(mode)||self.selected.is_none_or(|(selected,_,_)|selected!=body){return Err(ValueError::invariant("recipient child changed invocation, grant or control"))}if self.reply.is_none(){let owner=self.owner.as_mut().ok_or_else(||ValueError::invariant("original recipient is absent"))?;let child=crate::OriginalEffectReply::borrow(&mut self.reply)?;if let Some(original)=original.as_mut(){if recover{ErasedSnapshotRetirement::recover_close_original_into(owner,original,body,effect,child)?;}else{ErasedSnapshotRetirement::close_original_into(owner,original,body,effect,child)?;}}else if recover{ErasedSnapshotRetirement::recover_close_into(owner,body,effect,child)?;}else{ErasedSnapshotRetirement::close_into(owner,body,effect,child)?;}}if self.reply.is_none(){return Ok(reply.pending())}let work=effect.performed_since(boundary)?;let mut scope=reply.scope(&mut self.invocation,identity)?;let parent=scope.borrow()?;self.grant=None;self.selected=None;self.original=None;let result=self.reply.take().expect("original recipient reply retained");parent.complete(result.map(|step|RetirementStep::Progress(step.progress(),work)));Ok(scope.forwarded())}
}
impl RetirementCursor for NativeDecodeRecipientCursor{
 fn close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::OriginalEffectReply<'r,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::OriginalEffectReplyComplete<'r,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.close_reply(None,body,effect,reply,false)}
 fn recover_close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::OriginalEffectReply<'r,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::OriginalEffectReplyComplete<'r,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.close_reply(None,body,effect,reply,true)}
 fn close_original_into<'r>(&mut self,original:&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::OriginalEffectReply<'r,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::OriginalEffectReplyComplete<'r,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.close_reply(Some(original),body,effect,reply,false)}
 fn recover_close_original_into<'r>(&mut self,original:&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::OriginalEffectReply<'r,RetirementStep,crate::OriginalRetirementFailure>)->Result<crate::OriginalEffectReplyComplete<'r,RetirementStep,crate::OriginalRetirementFailure>,ValueError>{self.close_reply(Some(original),body,effect,reply,true)}
 fn requires_original_control(&self)->bool{self.owner.as_ref().is_some_and(ErasedSnapshotRetirement::requires_original_control)}
 fn requires_original_birth(&self)->bool{self.invocation.is_none()&&self.owner.as_ref().is_some_and(ErasedSnapshotRetirement::requires_original_birth)}
 fn close_original_birth_step(&mut self,original:&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->RetirementStep{match self.owner.as_mut(){Some(owner)if self.invocation.is_none()=>semio_framework_value_retirement::retirement::erased_cursor_turn(ErasedSnapshotRetirement::close_original_birth_step(owner,original,grant)),_=>RetirementStep::BudgetExhausted}}
 fn next_computational_work(&self,body:usize)->Result<u64,ValueError>{if let Some((selected,_,work))=self.selected{return if selected==body{Ok(work)}else{Err(ValueError::invariant("recipient close body changed"))}}match self.owner.as_ref(){None=>Ok(0),Some(owner)if owner.terminal_is_empty()=>Ok(1),Some(owner)=>ErasedSnapshotRetirement::next_computational_work(owner,body)}}
 fn next_demand(&self,body:usize)->Result<crate::RetirementDemand,ValueError>{if let Some((selected,demand,_))=self.selected{return if selected==body{Ok(demand)}else{Err(ValueError::invariant("recipient close body changed"))}}match self.owner.as_ref(){None=>Ok(Default::default()),Some(owner)if owner.terminal_is_empty()=>Ok(crate::RetirementDemand{copy_bytes:size_of::<Option<NativeDecodeRetirementRecipient>>(),depth:1,..Default::default()}),Some(owner)=>ErasedSnapshotRetirement::next_demand(owner,body)}}
 fn terminal_is_empty(&self)->bool{self.owner.is_none()&&self.reply.is_none()&&self.invocation.is_none()&&self.grant.is_none()&&self.selected.is_none()&&self.original.is_none()}
 fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(self.next_demand(0)?.depth)}
 fn next_work_byte_demand(&self)->Result<usize,ValueError>{Ok(self.next_demand(0)?.copy_bytes)}
 fn allows_admitted_narrow_work(&self)->bool{true}
 fn next_close_byte_demand(&self)->Option<usize>{self.next_demand(0).ok().map(|d|d.release_bytes)}
 fn next_birth_bytes(&self,body:usize)->Option<usize>{self.next_demand(body).ok().map(|d|d.capacity_bytes)}
 fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(size_of::<Self>())}
}
impl Drop for NativeDecodeRecipientCursor{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original recipient cursor retains its owner or child reply")}}
